export type paymentControllerPayResponse = (paymentControllerPayResponseSuccess | paymentControllerPayResponseError)

export const getPaymentControllerPayUrl = (paymentId: string,) => {


  

  return `/api/payments/${paymentId}`
}

export const paymentControllerPay = async (paymentId: string,
    payPaymentDto: PayPaymentDto, options?: RequestInit): Promise<paymentControllerPayResponse> => {
  
  return fetcher<paymentControllerPayResponse>(getPaymentControllerPayUrl(paymentId),
  {      
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(
      payPaymentDto,)
  }
);}
